"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[1438],{2(a){a.exports=JSON.parse('{"title":"Enum \uaf2d \uc368\uc57c \ud558\ub098\uc694?","date":"2024-08-30","coverUrl":null,"html":"<h2 data-notion-block-id=\\"8719035f-6f4a-4b11-8960-8a2fc63848c7\\" id=\\"8719035f-6f4a-4b11-8960-8a2fc63848c7\\">Enum \uaf2d \uc368\uc57c \ud558\ub098\uc694?</h2><a href=\\"https://www.totaltypescript.com/why-i-dont-like-typescript-enums\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.totaltypescript.com/why-i-dont-like-typescript-enums</a><p data-notion-block-id=\\"23175f63-e782-4a81-b51a-52d8cb9c05d7\\"><b>\uc2ec\uc724\uc12d</b>: TypeScript\uc5d0\uc11c enum\uc744 \uc0ac\uc6a9\ud558\uac8c \ub418\uba74 \ud2b8\ub79c\uc2a4\ud30c\uc77c \uacb0\uacfc\ubb3c\uc5d0 \uc218\uc0c1\ud55c IIFE \uacb0\uacfc\ubb3c\uc774 \ub098\uc624\uac8c \ub418\uace0, \uc774\ub294 \uc5ec\ub7ec\uac00\uc9c0 \ubc84\uadf8\ub97c \ubc1c\uc0dd\uc2dc\ud0b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 enum\uc744 \uc0ac\uc6a9\ud558\ub294 \uac83\uc744 \uad8c\uc7a5\ud558\uc9c0 \uc54a\uc8e0. \uc124\uba85\ud55c \uc774\uc720 \uc678\uc5d0\ub3c4 enum\uc744 \uc0ac\uc6a9\ud558\uba74 \uc54a\uc558\uc73c\uba74 \ud558\ub294 \uc774\uc720\uc5d0 \ub300\ud574 \uc124\uba85\ud558\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"d542897f-ad5e-46f8-a791-3becd97f0332\\" id=\\"d542897f-ad5e-46f8-a791-3becd97f0332\\">JavaScript\uc758 \uc0c8\ub85c\uc6b4 \ub0a0\uc9dc \uacc4\uc0b0 API</h2><a href=\\"https://docs.timetime.in/blog/js-dates-finally-fixed/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://docs.timetime.in/blog/js-dates-finally-fixed/</a><p data-notion-block-id=\\"0bb2aaef-4a2e-4cfc-b713-184d855aa004\\"><b>\uc2ec\uc724\uc12d</b>: \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\uc5d0\uc11c Date\ub97c \ub2e4\ub8f0 \ub54c Offset\uacfc \uae30\uac04, \uc0b0\uc218\ub97c \ucc98\ub9ac\ud558\uae30 \uc5b4\ub824\uc6e0\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c <code>moment.js</code>\ub098 <code>dayjs</code>\uac19\uc740 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ud1b5\ud574 \ub2e4\ub8f0 \uc218 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. \ud604\uc7ac \ud45c\uc900\uc774 \ub418\uae30 \ubc14\ub85c \uc804 \ub2e8\uacc4\uc5d0\uc11c \uc774\ub97c \ubaa8\ub450 \ucc98\ub9ac\ud560 \uc218 \uc788\ub294 <code>Temporal API</code>\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ud3f4\ub9ac\ud544\ub3c4 \uc81c\uacf5\ud558\uace0, Deno\uc5d0\uc11c\ub294 \uc9c1\uc811 \uc81c\uacf5\ud558\uace0 \uc788\ub2e4\uace0 \ud558\ub2c8, \uad00\uc2ec\uac00\uc9c8\ub9cc \ud558\ub124\uc694.</p><p data-notion-block-id=\\"3712c9b0-d6f9-48c9-84d9-3d962dd6b0bb\\">\uae40\ub300\uad00: \uae30\uc874 Date \uc0ac\uc6a9\uc790\ub4e4\uc5d0\uac8c\ub294 <code>moment.js</code>\ub098 <code>dayjs</code> \uac00 \ub9e4\uc6b0 \ud65c\uc6a9\ud558\uae30 \ud3b8\ud558\uae30 \ub54c\ubb38\uc5d0 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc744 \ub300\uccb4\ud560 \uc218 \uc788\uc744\uc9c0\ub294 \uc544\uc9c1 \ubaa8\ub974\uaca0\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc, \ubd88\ubcc0\uc131\uacfc \uc77c\uad00\uc131\uc5d0 \ub6f0\uc5b4\ub098\uace0, \uc5ec\ub7ec \uae30\ub2a5\uc774 \ucd94\uac00\ub420 \uc218 \uc788\ub294 <code>Temporal API</code> \uc758 \ud65c\uc6a9\uc774 \uc5b4\ub5bb\uac8c \ud655\uc7a5\ub420\uc9c0 \uc8fc\ubaa9\ud560 \ub9cc\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"4c16238f-3492-4dd4-ade0-8b1d8d184f43\\" id=\\"4c16238f-3492-4dd4-ade0-8b1d8d184f43\\">\ud06c\ub86c \ubc88\uc5ed\uc73c\ub85c\ubd80\ud130 \uc6f9\ud398\uc774\uc9c0 \ubcf4\ud638\ud558\uae30</h2><a href=\\"https://martijnhols.nl/gists/everything-about-google-translate-crashing-react\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://martijnhols.nl/gists/everything-about-google-translate-crashing-react</a><p data-notion-block-id=\\"3ff9ec40-0513-460c-aac8-7cec7e7fe65c\\">\uc6f9\ud398\uc774\uc9c0\ub97c \ud06c\ub86c \ubc88\uc5ed\uc744 \ud558\uac8c \ub418\uba74 \uc624\ub958\ub098\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc740\ub370, \ud06c\ub86c \ubc88\uc5ed\uc774 \uc5b4\ub5bb\uac8c \uc791\ub3d9\ud558\uace0 \uc5b4\ub5bb\uac8c \ubc29\uc5b4\ud560 \uc218 \uc788\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub2e4\ub978 \ud655\uc7a5\ud504\ub85c\uadf8\ub7a8\uc758 \uacbd\uc6b0\uc5d0\ub3c4 \uc624\ub958\ub97c \ubc1c\uc0dd\ud558\ub294 \uacbd\uc6b0\ub3c4 \uc788\uc73c\ub2c8 \uc54c\uace0 \uacc4\uc2dc\uba74 \uc88b\uc744 \uac83 \uac19\ub124\uc694!</p><h2 data-notion-block-id=\\"2aca4a36-2756-487b-af6f-c66c5446a767\\" id=\\"2aca4a36-2756-487b-af6f-c66c5446a767\\">\uc88b\uc740 \ub9ac\ud329\ud1a0\ub9c1\uc5d0 \ub300\ud55c \uace0\ucc30</h2><a href=\\"https://www.builder.io/blog/good-vs-bad-refactoring\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.builder.io/blog/good-vs-bad-refactoring</a><p data-notion-block-id=\\"32aca72e-212e-456e-8444-08fadf9f54de\\"><b>\uc2ec\uc724\uc12d</b>: \ucf54\ub4dc \uc2a4\ud0c0\uc77c(\ud639\uc740 \ud328\ub7ec\ub2e4\uc784)\uc744 \uc644\uc804\ud788 \ubcc0\uacbd\ud568, \ucd94\uc0c1\ud654\ub97c \ubd88\ud544\uc694\ud558\uac8c \uc9c4\ud589\ud568\u2026 \uac19\uc740 \ub098\uc05c \ub9ac\ud329\ud1a0\ub9c1\uc5d0 \ub300\ud55c \uc2e4\uc0ac\ub840\ub97c \uc0b4\ud3b4\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \uc88b\uc740 \ub9ac\ud329\ud1a0\ub9c1\uc5d0 \ub300\ud574 \uc815\uc758\ud558\ub294 \uae00\uc740 \uc544\ub2c8\uc9c0\ub9cc, <a href=\\"https://ones-to-watch.ethansup.net/news/post/f51019e1-e38c-4b60-a636-aab2334f6e8b#ec85017c-c8bc-46e1-abbe-e69801686efa\\">\uc801\uc808\ud55c \ucd94\uc0c1\ud654</a>\uc640 \uae30\uc874 \ucf54\ub4dc\uc640 \uc2a4\ud0c0\uc77c\uc744 \uc774\ud574\ud558\uace0 \uc810\uc9c4\uc801\uc73c\ub85c \uc77c\uad00\uc131 \uc788\uac8c \ub9ac\ud329\ud1a0\ub9c1\ud558\ub77c\ub294 \uac04\ub2e8\ud55c \uae00\uc785\ub2c8\ub2e4. \uc27d\uc9c0 \uc54a\uc8e0. \uadf8\ub798\uc11c \uc774 \uae00\uc5d0\uc11c\ub3c4 \ub9b0\ud2b8 \ub3c4\uad6c, \ucf54\ub4dc \uc791\uc131 \uc6d0\uce59, \ud14c\uc2a4\ud2b8\ub97c \ud1b5\ud574 \ub9ac\ud329\ud1a0\ub9c1\uc744 \uc790\ub3d9\uc73c\ub85c \uad8c\ud558\uac8c \ud558\ub3c4\ub85d \uc124\uc815\ud558\ub294 \uac83\uc744 \uad8c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"abc450dd-6ed0-4c64-916f-8bb1757cc4bd\\" id=\\"abc450dd-6ed0-4c64-916f-8bb1757cc4bd\\">\uc815\uaddc\ud45c\ud604\uc2dd\uc758 \uc9c4\ud654, \uadf8\ub9ac\uace0\u2026</h2><a href=\\"https://www.smashingmagazine.com/2024/08/history-future-regular-expressions-javascript/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.smashingmagazine.com/2024/08/history-future-regular-expressions-javascript/</a><p data-notion-block-id=\\"5bcf691f-2198-466e-97dd-d30a87ea16c0\\"><b>\uc2ec\uc724\uc12d</b>: \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\uc758 \uc815\uaddc\ud45c\ud604\uc2dd \uae30\ub2a5\uc740 \ub9e4\uc6b0 \ub9ce\uc2b5\ub2c8\ub2e4. lookahead, lookbehind\ubd80\ud130 \uc2dc\uc791\ud574\uc11c \uc544\uc9c1\ub3c4 \ucd94\uac00\ub418\uace0 \uc788\uc8e0. regex\ub77c\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc18c\uac1c\ud558\ub294 \uac83\uc774 \uc8fc\uc778 \uae00\uc774\uc9c0\ub9cc, \uc790\ubc14\uc2a4\ud06c\ub9bd\ud2b8\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ubc1c\uc804\ud588\uace0, \ubbf8\ub798\uc5d0 \ud45c\uc900\uc5d0 \ub4e4\uc5b4\uc62c \uc81c\uc548\ub4e4\uc744 \uc0b4\ud3b4\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"e7992d68-cd34-4f22-bccf-f687efba8317\\" id=\\"e7992d68-cd34-4f22-bccf-f687efba8317\\">Nuxt Script..</h2><a href=\\"https://nuxt.com/blog/nuxt-scripts\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nuxt.com/blog/nuxt-scripts</a><p data-notion-block-id=\\"80267e39-9d7d-493a-822b-3c656e06c2f4\\"><b>\uc2ec\uc724\uc12d</b>: \uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 <code>@next/third-parties</code>\ud328\ud0a4\uc9c0 \uc18c\uac1c(<a href=\\"https://ones-to-watch.ethansup.net/news/post/30480561-d12b-484b-9886-1eafeb5b6d35#d215dff3-0b22-4545-9c01-d944a4809548\\">NextJS\uc758 \uc11c\ub4dc\ud30c\ud2f0 \uc2a4\ud06c\ub9bd\ud2b8\ub97c \uc704\ud55c \ub178\ub825</a>)\uc640 \ube44\uc2b7\ud558\uac8c Nuxt\uc5d0\uc11c \ud0c0\uc0ac \uc2a4\ud06c\ub9bd\ud2b8\ub97c \ubaa8\ub4c8\ub85c\uc11c \uc81c\uacf5\ud558\ub294 <code>@nuxt/scripts</code>\ud328\ud0a4\uc9c0 \uc18c\uac1c \uae00\uc785\ub2c8\ub2e4. \ub180\ub77c\uc6b4 \uc810\uc740 \uc2a4\ud06c\ub9bd\ud2b8 \ubc88\ub4e4\ub9c1 \ud6c4 \uc81c\uacf5, \uc2a4\ud06c\ub9bd\ud2b8 \uc624\ud504\ub85c\ub4dc(\uc2a4\ud06c\ub9bd\ud2b8\ub97c \uc11c\ubc84\uc5d0\uc11c\ub9cc \ub85c\ub529, \uc608\uc815)\uae30\ub2a5\uc774\ub124\uc694. \uc774\uc678\uc5d0\ub3c4 Web worker\ub97c \ud1b5\ud574 \uc11c\ub4dc\ud30c\ud2f0 \uc2a4\ud06c\ub9bd\ud2b8\ub97c \ubd88\ub7ec\uc624\ub294 <a href=\\"https://github.com/BuilderIO/partytown\\">partytown</a>\uc5d0 \ub300\ud574\uc11c\ub3c4 \uc54c\uc544\ub450\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"23b64a2d-f30a-4eaf-9a8e-9b38facc77c0\\" id=\\"23b64a2d-f30a-4eaf-9a8e-9b38facc77c0\\">Branded \ud0c0\uc785</h2><a href=\\"https://www.learningtypescript.com/articles/branded-types\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.learningtypescript.com/articles/branded-types</a><p data-notion-block-id=\\"50be5b8b-9500-4c98-bb31-b3d19745877e\\"><b>\uc2ec\uc724\uc12d</b>: \ud0c0\uc785 \uc548\uc804\uc744 \uc704\ud574 \ub7f0\ud0c0\uc784\uc5d0\ub294 \uc0ac\uc6a9\ub418\uc9c0 \uc54a\ub294 \ucd94\uac00 \uc720\ud615\uc744 \ub9d0\ud558\ub294 Branded \ud0c0\uc785\uc744 \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc77c\ubc18\uc801\uc778 \uc0ac\uc6a9\ubc95\uacfc \uc7a5\ub2e8\uc810 \ubaa8\ub450 \uc18c\uac1c\ud558\uae30\uc5d0 \uc774\ub7ec\ud55c \uae30\ub2a5\uc744 \ud558\ub294 \ud0c0\uc785\uc744 \ub9cc\ub4e4 \uc218\ub3c4 \uc788\ub2e4\uace0 \ubcf4\uba74 \ub41c\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"91ac1cfb-7231-4434-aaf6-1b7471c1120c\\" id=\\"91ac1cfb-7231-4434-aaf6-1b7471c1120c\\">React \ucc98\uc74c\ubd80\ud130 \uad6c\ud604\ud558\uae30</h2><a href=\\"https://www.rob.directory/blog/react-from-scratch\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.rob.directory/blog/react-from-scratch</a><p data-notion-block-id=\\"d0a662b2-3bcf-4e09-8dce-00a23ab2bb5d\\">React\ub97c \ucc98\uc74c\ubd80\ud130 \uad6c\ud604\ud558\uba74\uc11c React\uc758 \ub80c\ub354\ub9c1 \uad6c\uc870\ub97c \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. <a href=\\"https://ones-to-watch.ethansup.net/news/post/022fc2c2-88d3-4c20-9075-defdea8ae65c#2d01841e-9fc5-4807-99d5-d8d2a73be23e\\">React \ub0b4\ubd80 \ub525 \ub2e4\uc774\ube0c</a>,  <a href=\\"https://ones-to-watch.ethansup.net/news/post/ce8b03b6-8565-440b-9d22-36c9ed0f58db#3107fecb-1574-47c1-94f0-f1a53442a6a4\\">React\uc758 \ub3d9\uc2dc\ubaa8\ub4dc \uc791\ub3d9 \uc6d0\ub9ac</a>\uc5d0\uc11c\ub3c4 \ub2e4\ub978 \ubc29\uc2dd\uc73c\ub85c \uc124\uba85\ud55c \uae00\uc744 \uc18c\uac1c\ud588\uc73c\ub2c8 \uc774\ud574 \ud558\uae30 \uc26c\uc6b4 \uae00\ub85c \uc811\uadfc\ud558\uc168\uc73c\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"82a200cb-b0b5-46e1-9b6e-fd16f6219592\\" id=\\"82a200cb-b0b5-46e1-9b6e-fd16f6219592\\">TypeScript \ud5f7\uac08\ub9ac\ub294 \ubd80\ubd84 \ud574\uacb0\ud558\uae30</h2><a href=\\"https://github.com/azat-co/50-ts\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/azat-co/50-ts</a><p data-notion-block-id=\\"fdd25b79-46b7-459f-a3de-66f1e0410009\\">TypeScript\uc5d0\uc11c \ud5f7\uac08\ub9b4 \uc218 \uc788\ub294 \ubd80\ubd84\uc744 \ub2e4\ub8ec \uae00\uc744 \ubaa8\uc740 \uae43\ud5c8\ube0c \uc800\uc7a5\uc18c\uc785\ub2c8\ub2e4.</p><p data-notion-block-id=\\"7eb08e99-86e7-4aed-bc53-d3646835ba7c\\"></p>"}')}}]);